@'
import { readFileSync, existsSync } from 'node:fs';
import { resolve, dirname, relative } from 'node:path';
import { createHash } from 'node:crypto';
import { loadPackageFromDirectory } from './packages/core/src/application/package-loader.ts';
import { validatePackage } from './packages/core/src/application/validate-package.ts';
import { NodeFileSystem } from './packages/node/src/file-system.ts';
const root = resolve('skills/g1-tuning-for-slo');
const loaded = await loadPackageFromDirectory(new NodeFileSystem(), root, { strict: true });
const validation = validatePackage(loaded.pkg, { directoryName: 'g1-tuning-for-slo', strict: true });
const files = ['SKILL.md','skill.yaml','references/derivation.md','references/flags-and-baselines.md','references/policy-log-and-troubleshooting.md'];
const links = [], missing = [];
let anchorCount = 0;
for (const file of files.filter(f => f.endsWith('.md'))) {
  const text = readFileSync(resolve(root,file),'utf8');
  for (const match of text.matchAll(/\[[^\]]+\]\(([^)]+)\)/g)) {
    if (/^[a-z]+:/i.test(match[1])) continue;
    const [target,anchor] = match[1].split('#');
    const absolute = target ? resolve(dirname(resolve(root,file)),target) : resolve(root,file);
    links.push({source:file,target:relative(root,absolute).replaceAll('\\','/'),anchor});
    if (!existsSync(absolute)) { missing.push(match[1]); continue; }
    if (anchor) {
      anchorCount++;
      const headings = [...readFileSync(absolute,'utf8').matchAll(/^#{1,6}\s+(.+)$/gm)]
        .map(m=>m[1].toLowerCase().replace(/[^\p{L}\p{N}\s_-]/gu,'').replace(/\s/g,'-'));
      if (!headings.includes(anchor)) missing.push(match[1]);
    }
  }
}
const finalHashes=Object.fromEntries(files.map(f=>[f,createHash('sha256').update(readFileSync(resolve(root,f))).digest('hex')]));
const unchangedReference=finalHashes['references/flags-and-baselines.md']==='3dc9efd8d85b0bda9a0a9b9e16c21c236cc8ec460ee6a40f480f38f5fb40ab66';
const result={package:loaded.pkg.manifest.name,version:loaded.pkg.manifest.version,files:loaded.pkg.files.length,issues:[...loaded.issues,...validation.issues],relativeLinks:links,anchorCount,missing,unchangedReference,finalHashes};
console.log(JSON.stringify(result,null,2));
if(result.issues.length||missing.length||!unchangedReference) process.exitCode=1;
'@ | node --input-type=module
